// For each WordPress post: the signals the GEO paper links to AI visibility, plus structure.
// Same rules as geo_tracker/audit.py and the WordPress plugin; n8n/test_code_nodes.js checks this code
// against the shared cases in tests/fixtures/signals_cases.json.
// JavaScript's \d only matches ASCII digits, Python's matches full-width ones too (３０％), so use \p{Nd}.
const STAT_RE = /(?<![\p{Nd}.])(?!(?:19|20)\p{Nd}\p{Nd}\s*年)\p{Nd}[\p{Nd},]*(?:\.\p{Nd}+)?\s*(?:%|％|萬|億|倍|元|美元|人|次|年)/gu;
const FAQ_RE = /FAQ|常見問題|Q\s*&\s*A/i;
// n8n's Code node sandbox has no URL class (found by testing), so hostnames are parsed with a regex
const hostOf = u => ((String(u).trim().match(/^https?:\/\/([^\/?#:\s]+)/i) || [])[1] || '').toLowerCase().replace(/^www\./, '');
const own = hostOf($('Config').first().json.base_url);
const isOwn = h => h === own || h.endsWith('.' + own);       // subdomains are ours; look-alikes are not
const ENTITIES = { '&nbsp;': ' ', '&amp;': '&', '&lt;': '<', '&gt;': '>', '&quot;': '"', '&#039;': "'" };
const strip = s => String(s || '')
  .replace(/<(script|style)\b[\s\S]*?<\/\1>/gi, ' ')
  .replace(/<[^>]+>/g, ' ')
  .replace(/&nbsp;|&amp;|&lt;|&gt;|&quot;|&#039;/g, m => ENTITIES[m])
  .replace(/\s+/g, ' ')
  .trim();

return $input.all().map(({ json: p }) => {
  const html = (p.content && p.content.rendered) || '';
  const text = strip(html);
  const headings = [...html.matchAll(/<h[23][^>]*>([\s\S]*?)<\/h[23]>/gi)].map(m => strip(m[1]));
  const hosts = new Set(
    [...html.matchAll(/href=["'](https?:\/\/[^"']+)["']/gi)].map(m => hostOf(m[1])).filter(h => h && !isOwn(h))
  );
  const modified = new Date((p.modified_gmt || p.modified) + 'Z');   // modified_gmt is UTC; modified is local time
  return {
    json: {
      id: p.id,
      title: strip(p.title && p.title.rendered),
      link: p.link,
      chars: [...text.replace(/\s/g, '')].length,        // zh-TW: characters (code points), not words
      headings: headings.length,
      has_faq: headings.some(h => FAQ_RE.test(h)),
      external_sources: hosts.size,                      // GEO: cite sources
      statistics: (text.match(STAT_RE) || []).length,    // GEO: statistics
      quotes: (html.match(/<blockquote/gi) || []).length + (text.match(/「/g) || []).length,
      tables: (html.match(/<table/gi) || []).length,
      days_since_update: Math.floor((Date.now() - modified) / 86400000),
    },
  };
});

// One summary item for the whole blog (same numbers and rounding as the Python and PHP versions).
const rows = $input.all().map(i => i.json);
const n = rows.length;
// Python's format() rounds halves to even (12.5% -> 12%); Math.round would give 13%.
const roundHalfEven = x => { const f = Math.floor(x), d = x - f; return d > 0.5 || (d === 0.5 && f % 2 === 1) ? f + 1 : f; };
const pct = f => roundHalfEven((rows.filter(f).length / n) * 100) + '%';
if (!n) return [{ json: { posts: 0 } }];
const chars = rows.map(r => r.chars).sort((a, b) => a - b);
return [{
  json: {
    posts: n,
    median_chars: chars[Math.floor(n / 2)],
    with_any_external_source: pct(r => r.external_sources > 0),
    with_3plus_statistics: pct(r => r.statistics >= 3),
    with_quotes: pct(r => r.quotes > 0),
    with_faq_section: pct(r => r.has_faq),
    updated_in_last_180_days: pct(r => r.days_since_update <= 180),
    posts_without_sources: rows.filter(r => r.external_sources === 0).map(r => r.title),
  },
}];
